DROP TABLE IF EXISTS `barang_work_unit`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `barang_work_unit` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `barang_id` bigint unsigned NOT NULL,
  `work_unit_id` bigint unsigned NOT NULL,
  `stok` int NOT NULL DEFAULT '0',
  `minimum_stok` int NOT NULL DEFAULT '5',
  `harga_jual_override` decimal(12,2) DEFAULT NULL,
  `harga_grosir_override` decimal(12,2) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `barang_work_unit_barang_id_work_unit_id_unique` (`barang_id`,`work_unit_id`),
  KEY `barang_work_unit_barang_id_index` (`barang_id`),
  KEY `barang_work_unit_work_unit_id_index` (`work_unit_id`),
  KEY `barang_work_unit_is_active_index` (`is_active`),
  CONSTRAINT `barang_work_unit_barang_id_foreign` FOREIGN KEY (`barang_id`) REFERENCES `barangs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `barang_work_unit_work_unit_id_foreign` FOREIGN KEY (`work_unit_id`) REFERENCES `work_units` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2126 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

