  `menu_rekomendasi` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Menu apa yang kamu rekomendasikan untuk ada di Kantin IKIP Siliwangi',
  `kritik_saran` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Kritik dan saran untuk kantin',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `member_surveys_user_id_foreign` (`user_id`),
  CONSTRAINT `member_surveys_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
