--
-- Table structure for table `pengajuan_barang`
--

DROP TABLE IF EXISTS `pengajuan_barang`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pengajuan_barang` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `barang_id` bigint unsigned NOT NULL,
  `work_unit_id` bigint unsigned NOT NULL,
  `diajukan_oleh` bigint unsigned NOT NULL,
  `diproses_oleh` bigint unsigned DEFAULT NULL,
  `jenis` enum('stok','nama_barang','kode_barang') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'stok',
  `nilai_lama` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nilai_baru` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `keterangan` text COLLATE utf8mb4_unicode_ci,
  `status` enum('pending','disetujui','ditolak') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `catatan_pengelola` text COLLATE utf8mb4_unicode_ci,
  `diproses_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `pengajuan_barang_barang_id_foreign` (`barang_id`),
  KEY `pengajuan_barang_work_unit_id_foreign` (`work_unit_id`),
  KEY `pengajuan_barang_diajukan_oleh_foreign` (`diajukan_oleh`),
  KEY `pengajuan_barang_diproses_oleh_foreign` (`diproses_oleh`),
  CONSTRAINT `pengajuan_barang_barang_id_foreign` FOREIGN KEY (`barang_id`) REFERENCES `barangs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pengajuan_barang_diajukan_oleh_foreign` FOREIGN KEY (`diajukan_oleh`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pengajuan_barang_diproses_oleh_foreign` FOREIGN KEY (`diproses_oleh`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pengajuan_barang_work_unit_id_foreign` FOREIGN KEY (`work_unit_id`) REFERENCES `work_units` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=139 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

