  CONSTRAINT `pengajuan_tambah_barang_diproses_oleh_foreign` FOREIGN KEY (`diproses_oleh`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pengajuan_tambah_barang_work_unit_id_foreign` FOREIGN KEY (`work_unit_id`) REFERENCES `work_units` (`id`) ON DELETE CASCADE
