--
-- Table structure for table `penjualan_items`
--

DROP TABLE IF EXISTS `penjualan_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `penjualan_items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `penjualan_id` bigint unsigned NOT NULL,
  `barang_id` bigint unsigned NOT NULL,
  `varian_id` bigint unsigned DEFAULT NULL,
  `nama_barang` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Snapshot nama barang saat transaksi',
  `qty` int NOT NULL COMMENT 'Jumlah barang',
  `satuan` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Satuan barang',
  `harga_satuan` decimal(12,2) NOT NULL COMMENT 'Harga per unit saat transaksi',
  `diskon_per_item` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Diskon per item',
  `subtotal` decimal(15,2) NOT NULL COMMENT 'Subtotal (qty * harga - diskon)',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `penjualan_items_penjualan_id_index` (`penjualan_id`),
  KEY `penjualan_items_barang_id_index` (`barang_id`),
  KEY `penjualan_items_varian_id_index` (`varian_id`),
  CONSTRAINT `penjualan_items_barang_id_foreign` FOREIGN KEY (`barang_id`) REFERENCES `barangs` (`id`),
  CONSTRAINT `penjualan_items_penjualan_id_foreign` FOREIGN KEY (`penjualan_id`) REFERENCES `penjualans` (`id`) ON DELETE CASCADE,
  CONSTRAINT `penjualan_items_varian_id_foreign` FOREIGN KEY (`varian_id`) REFERENCES `barang_varians` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=8732 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `penjualan_items`
--

LOCK TABLES `penjualan_items` WRITE;
/*!40000 ALTER TABLE `penjualan_items` DISABLE KEYS */;
