DROP TABLE IF EXISTS `vouchers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vouchers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `kode_voucher` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `potongan_id` bigint unsigned NOT NULL,
  `status` enum('draft','printed','used') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `penjualan_id` bigint unsigned DEFAULT NULL,
  `used_by` bigint unsigned DEFAULT NULL,
  `printed_at` timestamp NULL DEFAULT NULL,
  `used_at` timestamp NULL DEFAULT NULL,
  `created_by` bigint unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `vouchers_kode_voucher_unique` (`kode_voucher`),
  KEY `vouchers_potongan_id_foreign` (`potongan_id`),
  KEY `vouchers_penjualan_id_foreign` (`penjualan_id`),
  KEY `vouchers_used_by_foreign` (`used_by`),
  KEY `vouchers_created_by_foreign` (`created_by`),
  CONSTRAINT `vouchers_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `vouchers_penjualan_id_foreign` FOREIGN KEY (`penjualan_id`) REFERENCES `penjualans` (`id`),
  CONSTRAINT `vouchers_potongan_id_foreign` FOREIGN KEY (`potongan_id`) REFERENCES `potongan` (`id`),
  CONSTRAINT `vouchers_used_by_foreign` FOREIGN KEY (`used_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
